const body = $input.first().json.body;
if (!body || typeof body !== 'object' || Array.isArray(body)) {
  throw new Error('Bitte ein JSON-Objekt im Request-Body senden.');
}
const vin = String(body.vin ?? '').trim().toUpperCase();
if (!vin) throw new Error('Bitte das Pflichtfeld vin ausfüllen.');
const yearText = String(body.modelljahr ?? '').trim();
if (!/^\d{4}$/.test(yearText)) {
  throw new Error('Bitte modelljahr als vierstelliges Jahr angeben.');
}
return [{ json: { vin, modelljahr: Number(yearText) } }];

const response = $input.first().json;
if (!Array.isArray(response.Results) || !response.Results[0]) {
  throw new Error('Die API-Antwort enthält keine Fahrzeugdaten unter Results[0].');
}
const r = response.Results[0];
const text = value => String(value ?? '').trim();
const year = text(r.ModelYear);
return [{ json: {
  marke: text(r.Make) || 'unbekannt',
  modell: text(r.Model) || 'unbekannt',
  modelljahr: /^\d{4}$/.test(year) ? Number(year) : null,
  api_fehlercode: text(r.ErrorCode),
  api_hinweis: text(r.ErrorText),
  quelle: 'NHTSA vPIC',
  test_hinweis: 'Öffentliche Teil-FIN aus der API-Dokumentation; keine vollständige Fahrzeugidentifikation.'
} }];

const daten = $input.first().json;
return [{ json: {
  title: `${daten.marke} ${daten.modell} (${daten.modelljahr ?? 'unbekannt'})`,
  body: daten.bericht,
  userId: 1
} }];
